export function createContextQualityCommitQueue(){
 const queues=new WeakMap();
 async function flush(storage,queue){const batch=queue.pending.splice(0);try{
  const results=await Promise.allSettled(batch.map(p=>p.prepared));
  const failed=results.filter(r=>r.status==='rejected');if(failed.length)throw new AggregateError(failed.map(r=>r.reason),'Artifact preparation failed');
  await batch[0].assertCurrent();storage.events.transact(transaction=>{storage.events.verifyIntegrity();for(const result of results){const draft=result.value;const existing=storage.events.get(draft.eventId);transaction.append({...draft,occurredAt:existing?.occurredAt??draft.occurredAt})}});
  for(const p of batch)p.resolve();
 }catch(error){for(const p of batch)p.reject(error)}finally{queue.admitted-=batch.length;queue.scheduled=false;if(queue.pending.length)schedule(storage,queue)}}
 function schedule(storage,queue){if(queue.scheduled)return;queue.scheduled=true;setImmediate(()=>void flush(storage,queue))}
 return function commit(storage,assertCurrent,prepare){let queue=queues.get(storage);if(!queue){queue={pending:[],admitted:0,scheduled:false};queues.set(storage,queue)}if(queue.admitted>=16)return Promise.reject(Error('Quality commit admission exceeds bound'));queue.admitted++;
  const prepared=Promise.resolve().then(prepare).then(draft=>structuredClone(draft));
  const result=new Promise((resolve,reject)=>queue.pending.push({prepared,assertCurrent,resolve,reject}));prepared.then(()=>schedule(storage,queue),()=>schedule(storage,queue));return result;
 }
}

