import {mkdtemp,rm,writeFile} from 'node:fs/promises';
import {resolve} from 'node:path';
import {tmpdir} from 'node:os';
import {DatabaseSync} from 'node:sqlite';
const repo=process.cwd();
const {initializeActiveFixture}=await import(resolve(repo,'scripts/evaluation/lib/context-quality-active-fixture.mjs'));
const {activeWorker}=await import(resolve(repo,'scripts/evaluation/lib/context-quality-active-worker.mjs'));
const {SQLiteEventStore}=await import(resolve(repo,'packages/event-store-sqlite/dist/index.js'));
const {FileSystemCas}=await import(resolve(repo,'packages/cas/dist/index.js'));
const parent=await mkdtemp(resolve(tmpdir(),'lervo-phases-v5-'));const results=[];
try{
 for(const workload of ['cold','warm','concurrent']){
  const root=resolve(parent,workload);await initializeActiveFixture(root);const phases={};const restore=[];
  function wrap(obj,key,label,asyncMethod=false){const original=obj[key];obj[key]=function(...args){const k=typeof label==='function'?label(...args):label;const p=phases[k]??={calls:0,ms:0};p.calls++;const start=performance.now();if(asyncMethod)return (async()=>{try{return await original.apply(this,args)}finally{p.ms+=performance.now()-start}})();try{return original.apply(this,args)}finally{p.ms+=performance.now()-start}};restore.push(()=>obj[key]=original)}
  wrap(DatabaseSync.prototype,'exec',sql=>'sql.exec.'+sql.trim().replace(/\s+/g,' ').slice(0,90));
  wrap(DatabaseSync.prototype,'prepare',sql=>'sql.prepare.'+sql.trim().replace(/\s+/g,' ').slice(0,90));
  for(const k of ['verifyIntegrity','get','transact','close'])wrap(SQLiteEventStore.prototype,k,'events.'+k);
  wrap(SQLiteEventStore,'open','events.open',true);
  for(const k of ['put','get'])wrap(FileSystemCas.prototype,k,'cas.'+k,true);
  let r;try{r=await activeWorker(root,'candidate',workload,4096,{warmups:2,samples:20,concurrency:4})}finally{for(const f of restore.reverse())f()}
  results.push({workload,phases,semanticValid:r.semanticValid,integrity:r.integrity,eventCount:r.eventCount,expectedEventCount:r.expectedEventCount,samples:r.samples.map(s=>s.slice(0,2))});
 }
 await writeFile('/tmp/lervo-recording-phase-v5.json',JSON.stringify({diagnosticOnly:true,results},null,2));
}finally{await rm(parent,{recursive:true,force:true})}

import {readFileSync} from 'node:fs';
import { registerHooks } from 'node:module';
import { spawnSync } from 'node:child_process';
import { mkdtemp, rm, writeFile } from 'node:fs/promises';
import { resolve } from 'node:path';
import { tmpdir } from 'node:os';
const repo=process.cwd();
const worker=process.argv[2]==='worker';
if(worker){
 const [mode,root,workload]=process.argv.slice(3);
 let replacements=0;
 if(mode==='preparing-batch')registerHooks({load(url,context,next){const result=next(url,context);
if(url.endsWith('/packages/repository-context/dist/context-quality-commit.js')) {replacements++;return {...result,source:readFileSync('/tmp/lervo-preparing-commit-prototype.mjs','utf8')}}
if(!url.endsWith('/packages/repository-context/dist/context-quality-recording.js'))return result;
let source=String(result.source);
source=source.replace('const artifact = await storeVerificationBytes(storage.artifacts, bytes);','let artifact;\nconst eventId = `evt_${canonicalHash({ type: input.type, identity: input.identity }).slice(7, 39)}`;\nawait commitQualityEvent(storage, assertCurrent, async () => {\nartifact = await storeVerificationBytes(storage.artifacts, bytes);');
source=source.replace('await commitQualityEvent(storage, assertCurrent, {','return {');
source=source.replace('                payload,\n            });','                payload,\n            }; });');
replacements++;return {...result,source}}});
 const {activeWorker}=await import(resolve(repo,'scripts/evaluation/lib/context-quality-active-worker.mjs'));
 const r=await activeWorker(root,'candidate',workload,4096,{warmups:2,samples:10,concurrency:4});
 process.stdout.write(JSON.stringify({mode,workload,replacements,semanticValid:r.semanticValid,integrity:r.integrity,eventCount:r.eventCount,expectedEventCount:r.expectedEventCount,samples:r.samples.map(s=>s.slice(0,2))}));
}else{
 const {initializeActiveFixture}=await import(resolve(repo,'scripts/evaluation/lib/context-quality-active-fixture.mjs'));
 const parent=await mkdtemp(resolve(tmpdir(),'lervo-preparing-batch-'));const results=[];
 try{
  for(let cycle=0;cycle<5;cycle++)for(const workload of ['cold','warm','concurrent'])for(const mode of cycle%2?['preparing-batch','current']:['current','preparing-batch']){
   const root=resolve(parent,`${cycle}-${mode}-${workload}`);await initializeActiveFixture(root);
   const child=spawnSync(process.execPath,[process.argv[1],'worker',mode,root,workload],{encoding:'utf8',timeout:30000,maxBuffer:1048576});
   if(child.status!==0)throw Error(child.stderr||String(child.error));results.push({cycle,...JSON.parse(child.stdout)});
  }
  await writeFile('/tmp/lervo-preparing-batch-probe.json',JSON.stringify({diagnosticOnly:true,results},null,2));
 }finally{await rm(parent,{recursive:true,force:true})}
}

